def gauss_lemma_check(a,b,M):
  from math import floor
  p=a*a+b*b; res=[]
  for al in range(-2*p,2*p):
    for be in range(-2*p,2*p):
      X=al*a+be*b; Y=be*a-al*b
      if 0<=X<p and 0<=Y<p and (X,Y)!=(0,0): res.append((al,be,X,Y))
  f=[(al,be) for al,be,X,Y in res if 2*X<p and 2*Y<p]
  cnt=[0,0,0,0]
  for al,be in f:
    u,v=al*M[0]-be*M[1],al*M[1]+be*M[0]
    X=(u*a+v*b)%p; Y=(v*a-u*b)%p
    cnt[(0 if 2*X<p and 2*Y<p else 1 if 2*Y<p else 2 if 2*X>p else 3)]+=1
  return (cnt[1]+2*cnt[2]+3*cnt[3])%4
# compare with e where M^((p-1)/4) ≡ i^e mod a+bi, e.g. a,b=3,2 (p=13), M=(5,4)
